    if(memcmp(h,BT_PERSIST_MEDIA_MAGIC,8u)!=0||pm_r32(h+8u)!=BT_PERSIST_MEDIA_VERSION||pm_r32(h+12u)!=BT_PERSIST_MEDIA_HEADER)return BT_STATIC_ERR_BAD_ARGUMENT;
