    for(i=0;i<n;i++,p+=BT_PERSIST_MEDIA_ENTRY){unsigned side=p[0],idx=pm_r16(p+2u);if((side!=1u&&side!=2u)||p[1]!=0u||idx>=BT_D64_SECTORS||seen[side-1u][idx])return BT_STATIC_ERR_BAD_ARGUMENT;if(have_last&&(side<last_side||(side==last_side&&idx<=last_idx)))return BT_STATIC_ERR_BAD_ARGUMENT;have_last=true;last_side=side;last_idx=idx;seen[side-1u][idx]=1u;got[side-1u]++;}
